169	    @Test public void removeFormElement() {
170	        String html = "<html>\n" +
171	                "  <body> \n" +
172	                "      <form action=\"/hello.php\" method=\"post\">\n" +
173	                "      User:<input type=\"text\" name=\"user\" />\n" +
174	                "      Password:<input type=\"password\" name=\"pass\" />\n" +
175	                "      <input type=\"submit\" name=\"login\" value=\"login\" />\n" +
176	                "   </form>\n" +
177	                "  </body>\n" +
178	                "</html>  ";
179	        Document doc = Jsoup.parse(html);
180	        FormElement form = (FormElement) doc.selectFirst("form");
181	        Element pass = form.selectFirst("input[name=pass]");
182	        pass.remove();
183	
184	        List<Connection.KeyVal> data = form.formData();
185	        assertEquals(2, data.size());
186	        assertEquals("user", data.get(0).key());
187	        assertEquals("login", data.get(1).key());
188	        assertNull(doc.selectFirst("input[name=pass]"));
189	    }
