191	    @Test public void formSubmissionCarriesCookiesFromSession() throws IOException {
192	        String echoUrl = TestServer.origin().echo.url();
193	        Document cookieDoc = Jsoup.connect(TestServer.origin().cookie.url())
194	            .data(CookieRoute.SetCookiesParam, "1")
195	            .get();
196	        Document formDoc = cookieDoc.connection().newRequest() // carries cookies from above set
197	            .url(TestServer.origin().file.url("/htmltests/upload-form.html"))
198	            .get();
199	        FormElement form = formDoc.select("form").forms().get(0);
200	        Document echo = form.submit().post();
201	
202	        assertEquals(echoUrl, echo.location());
203	        Elements els = echo.select("th:contains(Cookie: One)");
204	        // ensure that the cookies are there and in path-specific order (two with same name)
205	        assertEquals("Echo", els.get(0).nextElementSibling().text());
206	        assertEquals("Root", els.get(1).nextElementSibling().text());
207	
208	        // make sure that the session following kept unique requests
