1	package org.jsoup.nodes;
2	
3	import org.jsoup.Connection;
4	import org.jsoup.Jsoup;
5	import org.jsoup.helper.HttpConnection;
6	import org.jsoup.helper.Validate;
7	import org.jsoup.internal.SharedConstants;
8	import org.jsoup.internal.StringUtil;
9	import org.jsoup.parser.Tag;
10	import org.jsoup.select.Elements;
11	import org.jsoup.select.Evaluator;
12	import org.jsoup.select.Selector;
13	import org.jspecify.annotations.Nullable;
14	
15	import java.util.ArrayList;
16	import java.util.List;
17	
18	/**
19	 * An HTML Form Element provides ready access to the form fields/controls that are associated with it. It also allows a
20	 * form to easily be submitted.
21	 */
22	public class FormElement extends Element {
23	    private final Elements linkedEls = new Elements();
24	    // contains form submittable elements that were linked during the parse (and due to parse rules, may no longer be a child of this form)
25	    private static final Evaluator formListed = Selector.evaluatorOf(StringUtil.join(SharedConstants.FormListedTags, ", "));
26	
27	    /**
28	     * Create a new, standalone form element.
29	     *
30	     * @param tag        tag of this element
31	     * @param baseUri    the base URI
32	     * @param attributes initial attributes
33	     */
34	    public FormElement(Tag tag, @Nullable String baseUri, @Nullable Attributes attributes) {
35	        super(tag, baseUri, attributes);
36	    }
37	
38	    /**
39	     * Get the list of form control elements associated with this form. Controls are returned in document order, and
40	     * may be descendants of this form, linked to it during parse error recovery, or associated via their
41	     * {@code form} attribute.
42	     * @return form controls associated with this element.
43	     */
44	    public Elements elements() {
45	        // As elements may have been added or removed from the DOM after parse, prepare a new list that unions them:
46	        Document doc = ownerDocument();
47	        Elements candidates;
48	        if (doc != null) {
49	            // scan the document so that controls moved by parse error recovery, and controls associated via their form
50	            // attribute, are all found in document order
51	            candidates = doc.select(formListed);
52	        } else {
53	            candidates = select(formListed); // current form children
54	            for (Element linkedEl : linkedEls) {
55	                if (linkedEl.ownerDocument() != null && !candidates.contains(linkedEl)) {
56	                    candidates.add(linkedEl); // adds previously linked elements, that weren't previously removed from the DOM
57	                }
58	            }
59	        }
60	
61	        Elements els = new Elements();
62	        for (Element el : candidates) {
63	            if (isAssociatedControl(el)) els.add(el);
64	        }
65	        return els;
66	    }
67	
68	    /**
69	     Tests if the element is a form control currently associated with this form: it is a descendant of the form; it was
70	     linked to the form during the parse, is still in the document, and has not been re-parented into another form; or
71	     its {@code form} attribute points to this form's ID. An explicit {@code form} attribute takes precedence over
72	     ancestor and parse-time association.
73	     */
74	    private boolean isAssociatedControl(Element el) {
75	        String formId = el.attr("form");
76	        if (!formId.isEmpty())
77	            return formId.equals(attr("id"));
78	
79	        boolean linked = linkedEls.contains(el);
80	        Element parent = el.parent();
81	        while (parent != null) {
82	            if (parent == this) return true; // simple child of this form
83	            if (parent.nameIs("form")) return false; // re-parented into a different form
84	            parent = parent.parent();
85	        }
86	        return linked && el.ownerDocument() != null;
87	    }
88	
89	    /**
90	     * Add a form control element to this form.
91	     * @param element form control to add
92	     * @return this form element, for chaining
93	     */
94	    public FormElement addElement(Element element) {
95	        linkedEls.add(element);
96	        return this;
97	    }
98	
99	    @Override
100	    protected void removeChild(Node out) {
101	        super.removeChild(out);
102	        linkedEls.remove(out);
103	    }
104	
105	    /**
106	     Prepare to submit this form. A Connection object is created with the request set up from the form values. This
107	     Connection will inherit the settings and the cookies (etc) of the connection/session used to request this Document
108	     (if any), as available in {@link Document#connection()}
109	     <p>You can then set up other options (like user-agent, timeout, cookies), then execute it.</p>
110	
111	     @return a connection prepared from the values of this form, in the same session as the one used to request it
112	     @throws IllegalArgumentException if the form's absolute action URL cannot be determined. Make sure you pass the
113	     document's base URI when parsing.
114	     */
115	    public Connection submit() {
116	        String action = hasAttr("action") ? absUrl("action") : baseUri();
117	        Validate.notEmpty(action, "Could not determine a form action URL for submit. Ensure you set a base URI when parsing.");
118	        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
119	                Connection.Method.POST : Connection.Method.GET;
120	
121	        Document owner = ownerDocument();
122	        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
123	        return connection.url(action)
124	                .data(formData())
125	                .method(method);
126	    }
127	
128	    /**
129	     * Get the data that this form submits. The returned list is a copy of the data, and changes to the contents of the
130	     * list will not be reflected in the DOM.
131	     * @return a list of key vals
132	     */
133	    public List<Connection.KeyVal> formData() {
134	        ArrayList<Connection.KeyVal> data = new ArrayList<>();
135	
136	        // iterate the form control elements and accumulate their values
137	        for (Element el : elements()) {
138	            if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
139	            if (isDisabled(el)) continue; // skip disabled form inputs
140	            String name = el.attr("name");
141	            if (name.length() == 0) continue;
142	            String type = el.attr("type");
143	
144	            if (type.equalsIgnoreCase("button") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these
145	
146	            if (el.nameIs("select")) {
147	                Elements options = el.select("option");
148	                boolean multiple = el.hasAttr("multiple");
149	                boolean set = false;
150	                for (Element option : options) {
151	                    if (!isEnabledOption(option)) continue; // skip disabled options and optgroups
152	                    if (option.hasAttr("selected")) {
153	                        data.add(HttpConnection.KeyVal.create(name, option.val()));
154	                        set = true;
155	                        if (!multiple) break; // a single select submits only its first selected option
156	                    }
157	                }
